    if(A.task==='target'&&!Number.isFinite(A.draft.driver.minimum)&&A.draft.driver.kind!=='sweep')return {text:'缺少目标电流，请在任务与参数填写。',module:'ampacity',tab:'parameters'};
    if(A.draft.driver.kind==='sweep'&&!A.draft.driver.samples.length)return {text:'请先选择扫描参数、范围和步长。',module:'sweep',tab:'settings',action:'设置扫描'};
