    for(const [key,value,label,unit]of [['insulation_mm',insulation,'绝缘厚度','mm'],['u0_kv',type.rating.u0/1000,'对地额定电压','kV']]){const f=fields[key];if(f&&(value<f.minimum||value>f.maximum))issues.push(label+' '+N(value,1)+' '+unit+' 超出插件范围 '+f.minimum+'–'+f.maximum+' '+unit);}
