    const pointer='/'+path.replaceAll('.','/');return Object.entries(ref.input_sources||{}).filter(([k])=>pointer===k||pointer.startsWith(k+'/')).sort((a,b)=>b[0].length-a[0].length)[0]?.[1]||null;
