  function undo(redo=false){const from=redo?A.redo:A.undo,to=redo?A.undo:A.redo;if(!from.length||A.viewRunId)return;const value=from.pop();to.push({...stateSnapshot(),restoreSelection:value.restoreSelection});H.state.draft=value.domain;A.draft=value.study;A.task=value.task;A.run=A.runs.find(r=>r.id===value.activeRunId)||null;A.caseId=value.caseId;H.state.dirty=JSON.stringify(H.state.draft)!==JSON.stringify(H.state.record.document);A.preflight=null;if(value.restoreSelection)StudySection.restoreSelection(value.selection);render();}
