      if(geometryStudy(item)){A.study=null;H.notify('这条记录属于型号几何；已打开对应的结构设计。载流量或温度计算请从首页新建研究。');location.hash='/types/'+item.workspace+'/structure';return;}
      Object.assign(A,{run:null,viewRunId:null,caseId:null,preflight:null,tabs:{},rows:{},inspectorClosed:{},checksOpen:false,undo:[],redo:[],comparison:null,delivery:null,extraModules:[]});A.compareIds.clear();A.deliveryIds.clear();await records();
