  function sharedReferences(){const snapshot=!!A.viewRunId||A.module==='method-compare'&&!!A.run&&currentResult(),d=snapshot?runInput():H.state.draft;if(!d?.cable_types)return '';const ps=d.sections[0].placements,depth=-ps.reduce((n,p)=>n+p.z,0)/ps.length,soil=d.materials.find(m=>m.id===d.sections[0].medium.material);return `<h3>共用输入 · 在所属模块修改</h3>${table(['对象','采用值','所属模块'],[[d.cable_types[0].label,N(d.cable_types[0].cores[0].conductor.nominal_area*1e6,0)+' mm²','cable','layers'],['平均中心埋深',N(depth,3)+' m','section','coordinates'],['土壤热阻率',N(soil?.thermal_resistivity,2)+' K·m/W','conditions',null],['负荷电流',N(d.load_cases[0].currents[d.circuits[0].id])+' A','conditions',null],['导体温限',N((d.criteria.max_conductor_temperature??d.cable_types[0].rating.max_conductor_temperature.normal)-273.15)+' °C','conditions',null]].map(([label,value,module,tab])=>`<tr><td>${E(label)}</td><td>${E(value)}</td><td>${snapshot?'运行快照':`<a href="${href(module,tab,null)}">查看 / 修改</a>`}</td></tr>`).join(''))}`;}
