    if(k==='change-task'){H.openDialog('更换研究任务',`<label class="amp-task-change">研究任务<select id="amp-task-change">${Object.entries(StudyShell.workflowNames).map(([key,label])=>`<option value="${key}" ${workflow()===key?'selected':''} ${supportsWorkflow(contract(),key)?'':'disabled'}>${label}${supportsWorkflow(contract(),key)?'':' · 当前方法不支持'}</option>`).join('')}</select></label><p class="subtle amp-inline-note">敷设、工况与型号引用保留；更换任务后原结果成为历史，需保存并重新计算。</p>`,B('应用任务','','apply-task','class="primary"'));return;}
    if(k==='apply-task'){const key=H.$('#amp-task-change').value;H.$('#modal').close();setWorkflow(key);return;}
    if(k==='modules'){H.openDialog('添加研究模块',`<div class="module-list">${StudyShell.modules.filter(m=>!activeModules().includes(m.id)).map(m=>`<div class="capability"><div><h3>${m.name}</h3><p class="subtle">${m.id==='thermal-field'?'结果与参数页面尚未接入。':'作为独立业务视图添加，切换不丢失输入。'}</p></div>${B('打开','','show-module-'+m.id)}</div>`).join('')||'<p>所有研究模块已显示。</p>'}</div>`);return;}
    if(k.startsWith('show-module-')){const id=k.slice(12);A.extraModules??=[];A.extraModules.push(id);H.$('#modal').close();go(id,id==='sweep'?'settings':id==='method-compare'?'inputs':null);return;}
